import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"ADR-001 — Polyrepo Architecture (7 Independent Repositories)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/adr-001-polyrepo.md","filePath":"adr/adr-001-polyrepo.md"}'),i={name:"adr/adr-001-polyrepo.md"};function n(d,e,s,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-001-—-polyrepo-architecture-7-independent-repositories" tabindex="-1">ADR-001 — Polyrepo Architecture (7 Independent Repositories) <a class="header-anchor" href="#adr-001-—-polyrepo-architecture-7-independent-repositories" aria-label="Permalink to &quot;ADR-001 — Polyrepo Architecture (7 Independent Repositories)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← ADR Index</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/polyrepo-structure.html">Polyrepo Structure</a> · <a href="./../architecture/local-run-architecture.html">Local Run Architecture</a></p><ul><li><strong>Status:</strong> Accepted</li><li><strong>Owners:</strong> Platform &amp; Service Leads (<code>BrandHubOrganization</code>)</li><li><strong>Related Docs:</strong> <a href="./../architecture/technical-overview.html">Technical Overview</a> · <a href="./../operations/deployment-acct134.html">Deployment Runbook</a> · <a href="./../rule/feature-workflow.html">Feature Workflow</a></li></ul><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p>BrandHub spans four distinct runtime ecosystems and deployment targets:</p><ol><li><strong>Reactive &amp; Servlet JVM Microservices (Java 21, Spring Boot 3 / Spring Cloud Gateway WebFlux)</strong> for perimeter routing, core business orchestration, SePay (VietQR) billing, and social publishing.</li><li><strong>Python AI &amp; Headless Browser Pipelines (Python 3.11+, FastAPI, PyTorch/SentenceTransformers, Playwright/Camoufox)</strong> for Brand Hybrid GraphRAG, trend crawling, compliance checks, and remote Vast.ai GPU orchestration.</li><li><strong>Browser SPA &amp; Static SEO Edge (TypeScript 6, React 19, Vite 8, Tailwind CSS 4)</strong> deployed to AWS S3 + CloudFront (<code>brandhub.id.vn</code>).</li><li><strong>Native Mobile Client (Expo SDK 58, React Native 0.88)</strong> built for Android/iOS devices with native camera, biometrics, and push notifications.</li><li><strong>Cloud Infrastructure &amp; Polyglot DDL (Terraform <code>~&gt; 6.0</code>, Docker Compose v2, SQL/Mongosh/Cypher, ComfyUI GPU bundles)</strong>.</li></ol><p>The 5-member engineering team needed to choose between a single multi-language monorepo and an independent polyrepo model with centralized architecture/infrastructure governance.</p><hr><h2 id="_2-evaluated-options" tabindex="-1">2. Evaluated Options <a class="header-anchor" href="#_2-evaluated-options" aria-label="Permalink to &quot;2. Evaluated Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Pros</th><th style="text-align:left;">Cons / Why Rejected or Selected</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Option A: Single Monorepo</strong> (<code>Nx</code> / <code>Turborepo</code> + Maven + Poetry + Expo)</td><td style="text-align:left;">Atomic cross-service commits; single PR for full-stack features</td><td style="text-align:left;">Severe CI matrix bloat; Metro/Expo workspace hoisting conflicts with Vite 8; heavy Python ML dependencies (<code>torch</code>, <code>chromadb</code>) slow down unrelated frontend/Java builds; noisy git history across 5 concurrent developers</td></tr><tr><td style="text-align:left;"><strong>Option B: Frontend vs Backend Split</strong> (2 repositories)</td><td style="text-align:left;">Separates UI from server code</td><td style="text-align:left;">Still couples Java 21 Maven builds (<code>business</code>, <code>gateway</code>, <code>publisher</code>) with Python FastAPI/Playwright containers and AWS Terraform state</td></tr><tr><td style="text-align:left;"><strong>Option C: Service-Aligned Polyrepo (7 Core Repositories)</strong> <em>(Selected)</em></td><td style="text-align:left;">Clean runtime/build toolchains; independent ECR images &amp; S3 deploys; clear ownership per squad member</td><td style="text-align:left;">Requires explicit cross-repo API/message contracts and workspace sync automation (<code>scripts/workspace/clone-all.bat</code>)</td></tr></tbody></table><hr><h2 id="_3-decision-architecture" tabindex="-1">3. Decision Architecture <a class="header-anchor" href="#_3-decision-architecture" aria-label="Permalink to &quot;3. Decision Architecture&quot;">​</a></h2><p>Adopt a <strong>7-repository Polyrepo</strong> under GitHub Organization <code>BrandHubOrganization</code>, using <code>brandhub-infrastructure</code> as the single source of truth for cross-service contracts, database schemas, local Docker stacks, GPU worker bundles, and AWS production IaC:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Repository</th><th style="text-align:left;">Tech Stack</th><th style="text-align:left;">Runtime Target &amp; Port</th><th style="text-align:left;">Primary Responsibility</th></tr></thead><tbody><tr><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;">Java 21, Spring Cloud Gateway (WebFlux)</td><td style="text-align:left;"><code>gateway</code> EC2 (<code>:8080</code> behind Nginx <code>:443</code>)</td><td style="text-align:left;">RS256 JWT verification, header sanitization, Redis rate limiting, HTTP &amp; STOMP routing</td></tr><tr><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;">Java 21, Spring Boot 3, JPA + JDBC + Spring Data Mongo</td><td style="text-align:left;"><code>core</code> EC2 (<code>172.31.24.149:8081</code>)</td><td style="text-align:left;">Core 9-domain business logic (<code>141</code> FRs), 2-tier RBAC, SePay ACID billing, AI credit &amp; S3 envelope crypto</td></tr><tr><td style="text-align:left;"><code>brandhub-ai-service</code></td><td style="text-align:left;">Python 3.11+, FastAPI, ChromaDB, Neo4j, PhoBERT</td><td style="text-align:left;"><code>ai</code> EC2 (<code>172.31.20.60:8082</code>)</td><td style="text-align:left;">Brand Hybrid GraphRAG, caption/image/ambassador/video generation, BM25 + Graph trend scoring</td></tr><tr><td style="text-align:left;"><code>brandhub-publisher-service</code></td><td style="text-align:left;">Java 21, Spring Boot 3, Spring AMQP, Redis</td><td style="text-align:left;"><code>core</code> EC2 (<code>172.31.24.149:8083</code>)</td><td style="text-align:left;">RabbitMQ consumer &amp; OAuth lifecycle for <strong>Facebook, Instagram, TikTok, and Threads</strong></td></tr><tr><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;">React 19.2, Vite 8.3, Tailwind 4.3, Yjs, TipTap</td><td style="text-align:left;">S3 <code>brandhub-web-prd-134875421878</code> + CloudFront (<code>:3000</code> local)</td><td style="text-align:left;">Bilingual (<code>vi</code>/<code>en</code>) Web SPA, collaborative editor, Video Space, analytics &amp; Admin console</td></tr><tr><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;">Expo 58, React Native 0.88, React 19.3</td><td style="text-align:left;">EAS / Android &amp; iOS (<code>:8090</code> Metro local)</td><td style="text-align:left;">Mobile task approvals, content requests, push notifications, QR login &amp; realtime chat</td></tr><tr><td style="text-align:left;"><code>brandhub-infrastructure</code></td><td style="text-align:left;">Terraform, Docker Compose, SQL/JS/Cypher, VitePress</td><td style="text-align:left;">GitHub Pages + AWS <code>134875421878</code> + Vast.ai</td><td style="text-align:left;">Schemas, migrations, local Compose stacks, <code>prod/</code> Terraform &amp; host configs, <code>gpu-workers/</code>, and <code>docs/</code></td></tr></tbody></table><p><em>(Auxiliary runtime repositories such as <code>brandhub-crawl</code> on <code>172.31.20.50:8084</code> and the <code>run-brandhub</code> local desktop runner follow the same sibling-directory convention.)</em></p><hr><h2 id="_4-real-codebase-ci-cd-grounding" tabindex="-1">4. Real Codebase &amp; CI/CD Grounding <a class="header-anchor" href="#_4-real-codebase-ci-cd-grounding" aria-label="Permalink to &quot;4. Real Codebase &amp; CI/CD Grounding&quot;">​</a></h2><ul><li><strong>Sibling Workspace Bootstrap</strong>: <code>scripts/workspace/clone-all.bat</code> clones or pulls all 7 repositories side-by-side in the parent workspace directory so relative build contexts (<code>../../../../brandhub-*</code> in <code>docker/compose/shared/apps.yaml</code>) resolve identically on every developer machine.</li><li><strong>Scoped OIDC CI/CD (<code>prod/terraform/01-iam/github-actions-role.tf</code>)</strong>: AWS IAM role <code>brandhub-github-actions</code> trusts <code>repo:BrandHubOrganization/brandhub-*:ref:refs/heads/{main,develop}</code>. Each service repository builds its own immutable ECR image (<code>brandhub/&lt;service&gt;:sha-&lt;commit&gt;</code>) and rolls out only its target EC2 container over AWS SSM (<code>AWS-RunShellScript</code>).</li><li><strong>Centralized Schema &amp; Contract Governance</strong>: All DDL changes (<code>database/init/init-postgres-v2.sql</code>, <code>database/init/init-mongo.js</code>, <code>database/migrations/</code>), REST envelopes (<a href="./../api/api-response-format.html">API Response Format</a>), and RabbitMQ schemas live in <code>brandhub-infrastructure</code> before implementation PRs land in application repos.</li></ul><hr><h2 id="_5-trade-offs-operational-impact" tabindex="-1">5. Trade-offs &amp; Operational Impact <a class="header-anchor" href="#_5-trade-offs-operational-impact" aria-label="Permalink to &quot;5. Trade-offs &amp; Operational Impact&quot;">​</a></h2><h3 id="positive-outcomes" tabindex="-1">Positive Outcomes <a class="header-anchor" href="#positive-outcomes" aria-label="Permalink to &quot;Positive Outcomes&quot;">​</a></h3><ul><li><strong>Zero Build Contamination</strong>: Updating <code>brandhub-publisher-service</code> builds in &lt; 60s and deploys only to <code>brandhub-publisher-service</code> on <code>core</code> EC2 without rebuilding <code>brandhub-web</code> or re-downloading Python ML wheels.</li><li><strong>Least-Privilege Secret Segregation</strong>: Repository and host <code>.env</code> scopes remain isolated (<code>gateway</code> never sees <code>JWT_PRIVATE_KEY</code>; <code>ai</code> never sees PostgreSQL or SePay credentials).</li><li><strong>Parallel Team Velocity</strong>: Frontend, Mobile, Core Backend, and AI/Data engineers merge and deploy independently with minimal rebase churn.</li></ul><h3 id="accepted-costs-mitigations" tabindex="-1">Accepted Costs &amp; Mitigations <a class="header-anchor" href="#accepted-costs-mitigations" aria-label="Permalink to &quot;Accepted Costs &amp; Mitigations&quot;">​</a></h3><ul><li><strong>Coordinated Multi-Repo Changes</strong>: Modifying an internal DTO (such as <code>PublishJobMessage</code> or <code>/api/v1/ai/*</code> payloads) requires sequenced PRs across producer and consumer repos, mitigated by backwards-compatible JSON fields and contract docs (<a href="./../architecture/business-ai-rest-contract.html">Business–AI REST Contract</a>).</li><li><strong>Local Multi-Repo Sync</strong>: Developers running full containerized integration (<code>docker/compose/shared/apps.yaml</code>) must pull sibling repos via <code>scripts/workspace/clone-all.bat</code>; day-to-day development avoids this by running only <code>docker/run_dev.bat</code> (<code>postgres</code>, <code>mongodb</code>, <code>redis</code>, <code>rabbitmq</code>) in Docker and starting target app repos on the host.</li></ul>',25)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
